 // Anything else: undefined.
+const base = (word: string) => word.slice(word.lastIndexOf('/') + 1);
+const isShort = (w: string) => w.length > 1 && w[0] === '-' && w[1] !== '-';
+const hasShort = (w: string, letters: string) => isShort(w) && [...letters].some((l) => w.includes(l));
+// Paths the shell expands or we cannot resolve before the command runs: $VAR and ~user.
+const unresolvable = (p: string) => p.includes('$') || /^~[^/]/.test(p);
+
+function checkGit(argv: string[], cwd: string): Hit | undefined {
+  const valueFlags = ['-C', '-c', '--git-dir', '--work-tree', '--namespace'];
+  let i = 1;
+  while (i < argv.length && argv[i].startsWith('-')) i += valueFlags.includes(argv[i]) ? 2 : 1;
+  const sub = argv[i];
+  const args = argv.slice(i + 1);
+  if (sub === 'push') {
+    const longForce = ['--force', '--force-with-lease', '--mirror', '--delete', '--prune'];
+    const force = args.some((w) => longForce.some((f) => w === f || w.startsWith(f + '=')) || hasShort(w, 'fd'));
+    const refspec = args.some((w) => !w.startsWith('-') && (w[0] === '+' || w[0] === ':'));
+    if (force || refspec) return { name: 'force-push', reason: 'git push would rewrite remote history' };
+  }
+  if (sub === 'reset' && args.includes('--hard')) return { name: 'reset-hard', reason: 'git reset --hard discards local changes' };
+  if (sub === 'clean') {
+    const dryRun = args.some((w) => w === '-n' || w === '--dry-run');
+    const force = args.some((w) => w === '--force' || hasShort(w, 'f'));
+    if (force && !dryRun) return { name: 'clean-force', reason: 'git clean -f deletes untracked files' };
+  }
+  return undefined;
+}
+
+function checkRm(argv: string[], cwd: string): Hit | undefined {
+  const rest = argv.slice(1);
+  const dd = rest.indexOf('--');
+  const opts = dd < 0 ? rest : rest.slice(0, dd);
+  const recursive = opts.some((w) => w === '--recursive' || hasShort(w, 'rR'));
+  if (!recursive) return undefined;
+  const targets = [...opts.filter((w) => !w.startsWith('-')), ...(dd < 0 ? [] : rest.slice(dd + 1))];
+  const bad = targets.length === 0 || targets.some((p) => unresolvable(p) || !insideWorkspace(p, cwd) || sameDir(p, cwd));
+  return bad ? { name: 'rm-outside', reason: 'recursive rm outside the working directory' } : undefined;
+}
+
+function checkFind(argv: string[], cwd: string): Hit | undefined {
+  const args = argv.slice(1);
+  if (!args.some((w) => w === '-delete' || w === '-exec' || w === '-execdir')) return undefined;
+  const firstFlag = args.findIndex((w) => w.startsWith('-'));
+  const starts = firstFlag < 0 ? args : args.slice(0, firstFlag);
+  const paths = starts.length ? starts : ['.'];
+  const bad = paths.some((p) => unresolvable(p) || !insideWorkspace(p, cwd));
+  return bad ? { name: 'rm-outside', reason: 'find would delete or run commands outside the working directory' } : undefined;
+}
+
 export function denyListed(argv: string[], cwd: string): Hit | undefined {
-  throw new Error('not implemented');
+  if (argv.length === 0) return undefined;
+  switch (base(argv[0])) {
+    case 'git':
+      return checkGit(argv, cwd);
+    case 'rm':
+      return checkRm(argv, cwd);
+    case 'find':
+      return checkFind(argv, cwd);
+    default:
