+import type { EventOf, SessionEvent } from '../types.ts';
+
+// Shortcuts that make work look done. Findings are flags and one reminder for the model; they never refuse a claim.
+export type FileChange = { path: string; added: string[]; removed: string[]; deleted: boolean };
+export type Finding = { rule: string; path: string; detail?: string };
+
+const CODE = /\.(m?[jt]sx?|cjs|py|go|rs|rb|java|kt|cs|c|cc|cpp|h|hpp)$/;
+const TEST = /(\.test\.|\.spec\.|_test\.|(^|\/)tests?\/|(^|\/)test_[^/]*$)/;
+const SKIP = /\b(?:test|it|describe)\.skip\(|\bx(?:it|describe|test)\(|\bt\.Skip(?:f|Now)?\(|@pytest\.mark\.skip|pytest\.skip\(/;
+const ASSERT = /\bexpect\(|\bassert|\bt\.(?:Error|Fatal)|assert_eq!/;
+const LINE_RULES: [string, RegExp][] = [
+  ['suppression', /@ts-(?:ignore|nocheck|expect-error)|eslint-disable|# type: ignore|# noqa|# pylint: disable|\/\/\s*nolint/],
+  ['swallowed-error', /catch\s*(?:\(\w*\))?\s*\{\s*\}|^\s*except\b.*:\s*pass\s*$/],
+  ['type-escape', /\bas any\b/],
+  ['stub', /throw new Error\(\s*['"`]not implemented|raise NotImplementedError|\bunimplemented!\(|\btodo!\(/i],
+];
+
+export function findSlop(changes: FileChange[]): Finding[] {
+  const out: Finding[] = [];
+  for (const c of changes) {
+    if (TEST.test(c.path)) {
+      const asserts = (ls: string[]) => ls.filter((l) => ASSERT.test(l)).length;
+      if (c.deleted) out.push({ rule: 'test-deleted', path: c.path });
+      else if (asserts(c.removed) > asserts(c.added)) out.push({ rule: 'test-weakened', path: c.path });
+      for (const l of c.added) if (SKIP.test(l)) out.push({ rule: 'test-skipped', path: c.path, detail: l.trim() });
+    }
+    if (!CODE.test(c.path)) continue;
+    for (const l of c.added) {
+      for (const [rule, re] of LINE_RULES) if (re.test(l)) out.push({ rule, path: c.path, detail: l.trim() });
+    }
+  }
+  return out;
+}
+
+export const flagLabel = (f: Finding) => (f.detail ? `${f.rule} ${f.path}: ${f.detail}` : `${f.rule} ${f.path}`);
+
+export const slopReminder = (flags: string[]) =>
+  `cedia found shortcuts in this run's changes that can make work look done:\n${flags.map((f) => `- ${f}`).join('\n')}\nFix each one, or say plainly why it is right. Your claim is not refused.`;
+
+// Reads a `git diff -U0` patch into per-file changes.
+export function changesFromPatch(patch: string): FileChange[] {
+  const out: FileChange[] = [];
+  let cur: FileChange | undefined;
+  let inHunk = false;
+  for (const line of patch.split('\n')) {
+    if (line.startsWith('diff --git ')) {
+      cur = { path: line.slice(line.lastIndexOf(' b/') + 3), added: [], removed: [], deleted: false };
+      out.push(cur);
+      inHunk = false;
+      continue;
+    }
+    if (!cur) continue;
+    if (line.startsWith('@@')) inHunk = true;
+    else if (!inHunk) {
+      if (line.startsWith('deleted file mode')) cur.deleted = true;
+    } else if (line.startsWith('+')) cur.added.push(line.slice(1));
+    else if (line.startsWith('-')) cur.removed.push(line.slice(1));
+  }
+  return out;
+}
+
+// Without snapshots, only edit and write calls show what the run changed.
+export function changesFromCalls(events: SessionEvent[]): FileChange[] {
+  const out: FileChange[] = [];
+  const intents = new Map<string, EventOf<'tool_intent'>>();
+  for (const e of events) {
+    if (e.kind === 'tool_intent') intents.set(e.callId, e);
+    if (e.kind !== 'tool_result' || e.status !== 'completed') continue;
+    const intent = intents.get(e.callId);
+    if (!intent) continue;
+    const path = String(intent.input.path);
+    if (intent.tool === 'write') out.push({ path, added: String(intent.input.content ?? '').split('\n'), removed: [], deleted: false });
+    if (intent.tool === 'edit' && Array.isArray(intent.input.edits)) {
+      for (const ed of intent.input.edits as { old_text?: string; new_text?: string }[]) {
+        out.push({ path, added: String(ed.new_text ?? '').split('\n'), removed: String(ed.old_text ?? '').split('\n'), deleted: false });
+      }
+    }
+  }
+  return out;
+}
