@@ -0,0 +1,29 @@
+import { describe, expect, test } from 'bun:test';
+import { cart } from '../src/cart/cart.ts';
+import { totals } from '../src/order/total.ts';
+
+// Expected values worked by hand from the rules in README.md. MUG = 450, BAG = 2200 cents.
+describe('pricing rules from README', () => {
+  test('exactly 10 units of a SKU get the 5% bulk discount', () => {
+    // 10 mugs = 4500; 5% = 225; discounted 4275; shipping 800; tax 7% of 5075 = 355.25 -> 355
+    expect(totals(cart('US', [['MUG', 10]]))).toMatchObject({ subtotal: 4275, coupon: 0, shipping: 800, tax: 355, total: 5430 });
+  });
+
+  test('exactly 50 units get the 10% bulk discount', () => {
+    // 50 bags = 110000; 10% = 11000; discounted 99000; free shipping; tax 20% = 19800
+    expect(totals(cart('UK', [['BAG', 50]]))).toMatchObject({ subtotal: 99000, shipping: 0, tax: 19800, total: 118800 });
+  });
+
+  test('bulk units are counted per SKU across lines', () => {
+    // MUG 6 + MUG 4 = 10 units -> 5% off 4500
+    const t = totals(cart('US', [['MUG', 6], ['MUG', 4]]));
+    expect(t).toMatchObject({ subtotal: 4275 });
+    expect(t.lines).toHaveLength(1);
+  });
+
+  test('shipping is decided on the discounted subtotal after the coupon', () => {
+    // 2 bags = 4400 >= 4000 before coupon; SAVE10 takes 440 -> 3960 < 4000, so shipping 700 applies
+    // tax 20% of 4660 = 932; total 3960 + 700 + 932 = 5592
+    expect(totals(cart('UK', [['BAG', 2]], 'SAVE10'))).toMatchObject({ subtotal: 4400, coupon: 440, shipping: 700, tax: 932, total: 5592 });
+  });
+});

