+import { expect, test } from 'bun:test';
+import { formatDuration, parseDuration } from '../src/duration.ts';
+import { slugify, uniqueSlug } from '../src/slug.ts';
+import { LRU } from '../src/lru.ts';
+
+test('parseDuration rules', () => {
+  expect(parseDuration(' 2d 4h ')).toBe(187_200_000);
+  expect(parseDuration('1.5h')).toBe(5_400_000);
+  expect(parseDuration('250ms')).toBe(250);
+  expect(parseDuration('1h 30m')).toBe(5_400_000);
+  for (const bad of ['', '10', '5x', 'h', '-1s']) {
+    expect(() => parseDuration(bad)).toThrow(`"${bad}"`);
+  }
+});
+
+test('formatDuration rules', () => {
+  expect(formatDuration(1_500)).toBe('1s500ms');
+  expect(formatDuration(0)).toBe('0s');
+  expect(formatDuration(90_000_000)).toBe('1d1h');
+  expect(() => formatDuration(-1)).toThrow();
+});
+
+test('slugify rules', () => {
+  expect(slugify('Straße Æther Øl Łódź Đ')).toBe('strasse-aether-ol-lodz-d');
+  expect(slugify('  --a  b--  ')).toBe('a-b');
+  expect(slugify('ab-cd-ef', 5)).toBe('ab-cd');
+  expect(slugify('abcdefgh', 5)).toBe('abcde');
+  expect(slugify('ab cdefgh', 5)).toBe('ab');
+});
+
+test('uniqueSlug skips taken suffixes', () => {
+  expect(uniqueSlug('post', new Set(['post', 'post-2']))).toBe('post-3');
+  expect(uniqueSlug('post', new Set())).toBe('post');
+});
+
+test('LRU expiry and eviction reasons', () => {
+  let t = 0;
+  const log: string[] = [];
+  const cache = new LRU<string, number>(2, 1000, () => t);
+  cache.onEvict = (k, _v, r) => log.push(`${k}:${r}`);
+  cache.set('a', 1);
+  t = 500;
+  cache.set('b', 2);
+  expect(cache.get('a')).toBe(1); // a becomes most recent
+  expect(cache.keys()).toEqual(['a', 'b']);
+  cache.set('c', 3); // evicts b (least recent)
+  expect(log).toEqual(['b:capacity']);
+  t = 1000; // a was set at 0 but touched only via get; set/get do not refresh ttl
+  expect(cache.size).toBe(1);
+  expect(cache.delete('c')).toBe(true);
+  expect(cache.delete('c')).toBe(false);
+  expect(log).toEqual(['b:capacity', 'c:delete']);
+});
+
+test('LRU removes expired entries before live ones on set', () => {
+  let t = 0;
+  const log: string[] = [];
+  const cache = new LRU<string, number>(2, 100, () => t);
+  cache.onEvict = (k, _v, r) => log.push(`${k}:${r}`);
+  cache.set('a', 1);
+  t = 50;
+  cache.set('b', 2);
+  t = 120; // a expired, b live
+  cache.set('c', 3);
+  expect(log).toEqual(['a:expired']);
+  expect(cache.keys()).toEqual(['c', 'b']);
+});

